      !! col_ao(ps_soff(p)+c).
      integer,  intent(in)    :: ncoltot, ncoef
      integer,  intent(in)    :: ps_np(nbas), ps_ncol(nbas), ps_soff(nbas), ps_coff(nbas)
      integer,  intent(in)    :: col_ao(ncoltot)
